<script setup lang="ts">
import { Refresh } from '@element-plus/icons-vue'
import { ElMessage } from 'element-plus'
import { onMounted, ref } from 'vue'

import { api } from '../api/client'
import PageHeader from '../components/PageHeader.vue'
import StatusTag from '../components/StatusTag.vue'
import { useSessionStore } from '../stores/session'

const session=useSessionStore();const loading=ref(false);const topology=ref<any>({});const runs=ref<any[]>([]);const drawer=ref(false);const detail=ref<any>(null)
async function load(){loading.value=true;try{const [a,r]=await Promise.all([api.get('/api/v1/agents'),api.get('/api/v1/agent-runs',{params:{project_id:session.currentProjectId,limit:100}})]);topology.value=a.data;runs.value=r.data}catch(e){ElMessage.error(e instanceof Error?e.message:'智能体运行加载失败')}finally{loading.value=false}}
async function show(id:string){try{detail.value=(await api.get(`/api/v1/agent-runs/${id}`)).data;drawer.value=true}catch(e){ElMessage.error(e instanceof Error?e.message:'运行详情加载失败')}}
onMounted(load)
</script>
<template><PageHeader title="智能体运行" description="查看 Agent 拓扑、模型使用和安全执行摘要，不展示隐藏推理"><el-button :icon="Refresh" @click="load">刷新</el-button></PageHeader><section class="section"><div class="section__header"><h2>多 Agent 拓扑</h2><span class="muted">Supervisor 规划，领域 Worker 无状态执行</span></div><div class="agent-grid"><div class="agent-node supervisor"><strong>{{topology.orchestrator?.name||'ReviewSupervisorAgent'}}</strong><span>审查计划与领域选择</span></div><div v-for="agent in topology.review_agents||[]" :key="agent.name" class="agent-node"><strong>{{agent.name}}</strong><span>{{agent.responsibility}}</span></div><div class="agent-node knowledge"><strong>{{topology.knowledge_agent?.name||'KnowledgeAgent'}}</strong><span>项目问答与 Function Calling</span></div></div></section><section class="section"><div class="section__header"><h2>运行记录</h2><span class="muted">{{runs.length}} 条</span></div><el-table v-loading="loading" :data="runs" table-layout="fixed"><el-table-column prop="run_type" label="类型" width="150"/><el-table-column prop="business_id" label="业务对象" min-width="180" show-overflow-tooltip/><el-table-column prop="status" label="状态" width="100"><template #default="s"><StatusTag :status="s.row.status"/></template></el-table-column><el-table-column prop="model" label="模型" min-width="150"/><el-table-column prop="provider" label="Provider" width="110"/><el-table-column prop="input_tokens" label="输入" width="80"/><el-table-column prop="output_tokens" label="输出" width="80"/><el-table-column prop="latency_ms" label="耗时(ms)" width="110"/><el-table-column label="" width="70"><template #default="s"><el-button link type="primary" @click="show(s.row.id)">详情</el-button></template></el-table-column></el-table></section><el-drawer v-model="drawer" title="运行详情" size="min(700px,92vw)"><el-descriptions v-if="detail" :column="2" border><el-descriptions-item label="运行ID">{{detail.id}}</el-descriptions-item><el-descriptions-item label="状态"><StatusTag :status="detail.status"/></el-descriptions-item><el-descriptions-item label="Prompt">{{detail.prompt_name}} / {{detail.prompt_version}}</el-descriptions-item><el-descriptions-item label="结束原因">{{detail.finish_reason||'-'}}</el-descriptions-item></el-descriptions><h3>步骤摘要</h3><el-table :data="detail?.steps||[]"><el-table-column prop="step_name" label="步骤"/><el-table-column prop="operation" label="操作"/><el-table-column prop="status" label="状态"><template #default="s"><StatusTag :status="s.row.status"/></template></el-table-column><el-table-column prop="latency_ms" label="耗时(ms)"/></el-table></el-drawer></template>
<style scoped>.agent-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;padding:18px}.agent-node{min-height:90px;padding:16px;border:1px solid #dce3e8;border-left:3px solid #0f8f7a;border-radius:4px;display:flex;flex-direction:column;gap:8px}.agent-node span{color:#687784;font-size:12px;line-height:1.5}.agent-node.supervisor{grid-column:1/-1;border-left-color:#b87911}.agent-node.knowledge{border-left-color:#4b73a4}@media(max-width:720px){.agent-grid{grid-template-columns:1fr}.agent-node.supervisor{grid-column:auto}}</style>
